configFiles.template:
//----------------------------
// Base settings
//----------------------------

// Server name
hostname "${Hostname}"

// Join password (empty = public)
sv_password "${PrivatePassword}"

// Remote console password
rcon_password "${RconPassword}"

// Cheats (enabling them disables stats and achievements)
sv_cheats 0

// Voice: 0 = team only, 1 = everyone hears everyone (mic icons hidden), 2 = everyone, mic icons shown
sv_alltalk ${AllTalk}

// Allow clients to download files (maps, textures) from the server
sv_allowdownload ${AllowDownload}
net_maxfilesize 64

//----------------------------
// Contagion settings
//----------------------------

// 1 = only AI zombies: no player zombies, players who die spectate
cg_zombie_ai_only ${ZombieAiOnly}

// 1 = becoming infected is disabled
cg_infection_disabled ${InfectionDisabled}

//----------------------------
// Logging and ban lists
//----------------------------
log on
sv_logfile 1
sv_logecho 0
sv_logbans 1
writeip
writeid

script.code:
//refAssemblies: System.Diagnostics.Process.dll, TCAdmin.Monitor.SDK.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Wine (Linux host) only: installs what the panel needs to run this Windows server - wine, winetricks, Xvfb and
// xdotool - with apt (Debian/Ubuntu) or dnf/yum (Red Hat), creates the service's Wine prefix and installs the
// Windows runtimes listed in Verbs into it. Idempotent: anything already present is skipped. Runs before the
// create/reinstall (host packages, so the panel's Wine check passes) and after it (the prefix, once the service user
// and the files exist).
if (!System.OperatingSystem.IsLinux()) return;

// Windows runtimes (winetricks verbs) the server needs inside the prefix.
var verbs = new string[] {  };
const string Executable = "contagionds.exe";

var tools = new (string Command, string[] Apt, string[] Rpm)[]
{
    ("wine", new[] { "wine", "wine64" }, new[] { "wine" }),
    ("wineserver", new[] { "wine", "wine64" }, new[] { "wine" }),
    ("winetricks", new[] { "winetricks" }, new[] { "winetricks" }),
    ("cabextract", new[] { "cabextract" }, new[] { "cabextract" }),
    ("Xvfb", new[] { "xvfb" }, new[] { "xorg-x11-server-Xvfb", "xorg-x11-server-Xvfb.x86_64" }),
    ("xdotool", new[] { "xdotool" }, new[] { "xdotool" }),
};
var apt = Shell("command -v apt-get", out _);
var installer = apt ? "DEBIAN_FRONTEND=noninteractive apt-get install -y " : Shell("command -v dnf", out _) ? "dnf install -y " : "yum install -y ";
var updated = false;
foreach (var tool in tools)
{
    if (Shell("command -v " + tool.Command, out _)) continue;
    var names = apt ? tool.Apt : tool.Rpm;
    ScriptConsole.WriteLine((object)(tool.Command + " is missing on this host; installing " + string.Join(" or ", names) + "."));
    var installed = names.Any(p => Shell(installer + p, out _));
    if (!installed && apt && !updated)
    {
        updated = Shell("DEBIAN_FRONTEND=noninteractive apt-get update", out _);
        installed = names.Any(p => Shell(installer + p, out _));
    }
    if (!installed || !Shell("command -v " + tool.Command, out _))
        throw new Exception(tool.Command + " is missing and could not be installed. Install one of these packages on the host: " + string.Join(", ", names));
}
Shell("wine --version", out var wineVersion);
ScriptConsole.WriteLine((object)("Wine on this host: " + wineVersion.Trim()));

var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/');
var exePath = Path.Combine(root, Executable);
// Before the create/reinstall the service files and its run-as configuration do not exist yet.
string user = null;
if (File.Exists(exePath))
{
    try { user = ServiceManagerService.GetServiceCredential(ThisService.ServiceId)?.UserName; }
    catch (FileNotFoundException) { }
}
if (string.IsNullOrEmpty(user) || !Shell("id -u '" + user + "'", out _))
{
    ScriptConsole.WriteLine((object)"The service is not created yet; the Wine prefix is prepared after the files are installed.");
    return;
}

// The panel starts the server with the prefix architecture of the executable (PE header): use the same one, or the
// panel's start would find a prefix of the other architecture.
var arch = PeArchitecture(exePath);
var prefix = Path.Combine(root, ".wine");
// Every Wine call as the service user with the environment the panel starts the server with (root would leave
// root-owned files in the prefix).
var wineEnv = "runuser -u '" + user + "' -- env WINEPREFIX='" + prefix + "' HOME='" + root
              + "' WINEARCH=" + arch + " WINEDEBUG=-all WINEDLLOVERRIDES='mscoree=;mshtml=' ";

// The first start creates the Wine prefix (about a minute), longer than the panel waits for the start that follows
// the create. Create the prefix here; the panel skips it when its marker file is present.
var marker = Path.Combine(prefix, ".tcadmin-initialized");
if (!File.Exists(marker))
{
    ScriptConsole.WriteLine((object)("Creating the Wine prefix (" + arch + ", about a minute)."));
    if (!Shell(wineEnv + "wineboot -u", out var bootOutput))
        throw new Exception("wineboot failed: " + string.Join("\n", bootOutput.Split('\n').TakeLast(15)));
    Shell(wineEnv + "wineserver -w", out _);
    Shell("runuser -u '" + user + "' -- sh -c \"date -u +%Y-%m-%dT%H:%M:%SZ > '" + marker + "'\"", out _);
    ScriptConsole.WriteLine((object)"The Wine prefix is ready.");
}

if (verbs.Length == 0) return;
// winetricks records every verb it installed in the prefix.
var log = Path.Combine(prefix, "winetricks.log");
var done = File.Exists(log) ? File.ReadAllLines(log).Select(l => l.Trim()).ToHashSet() : new HashSet<string>();
var todo = verbs.Where(v => !done.Contains(v)).ToList();
if (todo.Count == 0)
{
    ScriptConsole.WriteLine((object)("Windows runtimes already installed: " + string.Join(", ", verbs) + "."));
    return;
}
ScriptConsole.WriteLine((object)("Installing " + string.Join(", ", todo) + " into the Wine prefix (a few minutes)."));
if (!Shell(wineEnv + "winetricks -q " + string.Join(" ", todo), out var output))
    throw new Exception("winetricks failed: " + string.Join("\n", output.Split('\n').TakeLast(15)));
Shell(wineEnv + "wineserver -w", out _);
ScriptConsole.WriteLine((object)"Windows runtimes installed.");

static string PeArchitecture(string path)
{
    using (var stream = File.OpenRead(path))
    using (var reader = new BinaryReader(stream))
    {
        stream.Seek(0x3C, SeekOrigin.Begin);
        var peOffset = reader.ReadInt32();
        stream.Seek(peOffset + 4, SeekOrigin.Begin);
        return reader.ReadUInt16() == 0x14c ? "win32" : "win64";
    }
}

bool Shell(string cmd, out string text)
{
    using (var process = Process.Start(new ProcessStartInfo("/bin/sh", new[] { "-c", cmd }) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        var stderr = process.StandardError.ReadToEndAsync();
        text = process.StandardOutput.ReadToEnd() + stderr.Result;
        process.WaitForExit();
        return process.ExitCode == 0;
    }
}

using System;
using System.IO;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

var root = (string)ThisService.RootDirectory;

// The server writes steam_appid.txt next to itself only during its first run, which therefore starts without Steam
// (LAN only). Writing it before every start makes the first one work.
var appIdFile = Path.Combine(root, "steam_appid.txt");
if (!File.Exists(appIdFile) || File.ReadAllText(appIdFile).Trim('\0', '\r', '\n', ' ') != "238430")
{
    File.WriteAllText(appIdFile, "238430\n");
    ScriptConsole.WriteLine((object)"Wrote steam_appid.txt (238430).");
}
// Scripts run as root on Linux (Wine): give the file to the service user (same owner as the service root), otherwise
// the file manager hides it.
if (System.OperatingSystem.IsLinux())
{
    Globals.OperatingSystem.SetFileOwnerAutoDetect(appIdFile);
}

// -condebug appends to console.log forever; keep only the previous run next to the new one.
var log = Path.Combine(root, "contagion", "console.log");
if (File.Exists(log))
{
    File.Move(log, Path.Combine(Path.GetDirectoryName(log), "console.previous.log"), true);
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Contagion Workshop items are .vpk add-ons (maps, weapons, models). The panel downloaded the item; this moves its
// .vpk files to contagion/addons as "<id>_<file>.vpk", where the server mounts them when it starts. (An update first runs
// the uninstall script, which stops a running server: Windows locks mounted add-ons.)
// (The server's own Workshop list, contagion/collection.txt, is not used: the server queues it before it is logged on
// to Steam, and it reads ids above 2147483647 as 2147483647.)
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]{1,20}$")) throw new Exception("Unexpected Workshop id: " + fileId);
string downloaded = Convert.ToString(Dynamic.InstallPath);
if (string.IsNullOrEmpty(downloaded) || !Directory.Exists(downloaded))
    throw new Exception("The Workshop item was not downloaded (" + downloaded + ").");

var root = Path.GetFullPath((string)ThisService.RootDirectory);
var game = Path.Combine(root, "contagion");
NoLink(game);
var addons = Path.Combine(game, "addons");
NoLink(addons);
var createdAddons = !Directory.Exists(addons);
Directory.CreateDirectory(addons);
if (createdAddons && System.OperatingSystem.IsLinux()) Globals.OperatingSystem.SetDirectoryOwnerAutoDetect(addons, false);

NoLinkInside(downloaded);
var packages = Directory.GetFiles(downloaded, "*.vpk", SearchOption.AllDirectories)
    .Where(f => !f.Contains(Path.DirectorySeparatorChar + ".DepotDownloader" + Path.DirectorySeparatorChar)).ToList();
if (packages.Count == 0) throw new Exception("Workshop item " + fileId + " has no .vpk file; Contagion loads Workshop items only as .vpk add-ons.");

// An update replaces the previous files of this item.
foreach (var old in Directory.GetFiles(addons, fileId + "_*.vpk")) File.Delete(old);
var maps = new List<string>();
foreach (var package in packages)
{
    var target = Path.Combine(addons, fileId + "_" + Regex.Replace(Path.GetFileName(package), "[^A-Za-z0-9._()-]", "_"));
    File.Move(package, target, true);
    if (System.OperatingSystem.IsLinux()) Globals.OperatingSystem.SetFileOwnerAutoDetect(target);
    maps.AddRange(MapsIn(target));
    ScriptConsole.WriteLine((object)("Installed " + Path.GetFileName(target) + " in contagion/addons."));
}
// The download folder is only the panel's staging copy.
DeleteTree(downloaded);

if (maps.Count > 0)
    ScriptConsole.WriteLine((object)("Maps: " + string.Join(", ", maps) + ". Restart the server to load the add-on, then change to a map with: changelevel " + maps[0] +
        " (or pick it as the startup map in a custom command line). The map prefix sets the game mode."));
else
    ScriptConsole.WriteLine((object)"Restart the server to load the add-on.");

// Map names in a VPK directory (maps/<name>.bsp).
List<string> MapsIn(string vpk)
{
    var found = new List<string>();
    try
    {
        using (var r = new BinaryReader(File.OpenRead(vpk)))
        {
            if (r.ReadUInt32() != 0x55aa1234) return found;
            var version = r.ReadUInt32(); r.ReadUInt32();
            if (version == 2) r.ReadBytes(16);
            string Str() { var b = new List<byte>(); byte c; while ((c = r.ReadByte()) != 0) b.Add(c); return Encoding.UTF8.GetString(b.ToArray()); }
            while (true)
            {
                var ext = Str(); if (ext == "") break;
                while (true)
                {
                    var dir = Str(); if (dir == "") break;
                    while (true)
                    {
                        var name = Str(); if (name == "") break;
                        r.ReadUInt32(); var preload = r.ReadUInt16(); r.ReadBytes(12);
                        if (preload > 0) r.ReadBytes(preload);
                        if (ext == "bsp" && dir.Equals("maps", StringComparison.OrdinalIgnoreCase)) found.Add(name);
                    }
                }
            }
        }
    }
    catch (EndOfStreamException) { }
    return found;
}

void NoLink(string p)
{
    var info = new FileInfo(p);
    if ((info.Exists || Directory.Exists(p)) && info.Attributes.HasFlag(FileAttributes.ReparsePoint))
        throw new Exception(p + " is a link; refusing to write through it.");
}

// The download must not contain links (walked by hand: never descends into one).
void NoLinkInside(string dir)
{
    NoLink(dir);
    foreach (var e in new DirectoryInfo(dir).EnumerateFileSystemInfos())
    {
        if (e.Attributes.HasFlag(FileAttributes.ReparsePoint)) throw new Exception(e.FullName + " is a link; refusing to install the item.");
        if (e is DirectoryInfo) NoLinkInside(e.FullName);
    }
}

// Deletes a folder without following links inside it (a link is removed, never its target).
void DeleteTree(string path)
{
    foreach (var entry in new DirectoryInfo(path).EnumerateFileSystemInfos())
    {
        if (entry.Attributes.HasFlag(FileAttributes.ReparsePoint) || entry is FileInfo) entry.Delete();
        else DeleteTree(entry.FullName);
    }
    Directory.Delete(path);
}

using System;
using System.IO;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Deletes the Workshop item's add-ons (contagion/addons/<id>_*.vpk). The script is marked "stop the service": Windows locks
// mounted add-ons, so the panel stops a running server before this runs and starts it again after.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]{1,20}$")) throw new Exception("Unexpected Workshop id: " + fileId);

var root = Path.GetFullPath((string)ThisService.RootDirectory);
var addons = Path.Combine(root, "contagion", "addons");
foreach (var p in new[] { Path.Combine(root, "contagion"), addons })
{
    var info = new DirectoryInfo(p);
    if (info.Exists && info.Attributes.HasFlag(FileAttributes.ReparsePoint)) throw new Exception(p + " is a link; refusing to touch it.");
}
var removed = 0;
if (Directory.Exists(addons))
{
    foreach (var file in Directory.GetFiles(addons, fileId + "_*.vpk"))
    {
        File.Delete(file);
        removed++;
        ScriptConsole.WriteLine((object)("Deleted contagion/addons/" + Path.GetFileName(file) + "."));
    }
}
ScriptConsole.WriteLine((object)(removed == 0 ? "No add-on of Workshop item " + fileId + " was installed." : "The server no longer loads it."));
